&reftitle.description;
public Yaf_View_SimpleYaf_View_Simple::setScriptPath stringtemplate_dir
Define o diretório no qual os modelos são procurados.

  &reftitle.parameters;


    template_dir

O diretório no qual os scripts de modelo são armazenados.

  &reftitle.examples;

   Exemplo de Yaf_View_Simple::setScriptPath


<?php
class IndexController extends Yaf_Controller_Abstract
{
    public function indexAction()
    {
        /* renderiza modelos de outro diretório */
        $this->getView()->setScriptPath(APPLICATION_PATH . "/modules/admin/views");

        $this->getView()->display("dashboard/index.phtml");

        return false; // a renderização foi feita manualmente; ignora a renderização automática
    }
}
?>
